# Let's test for backdoor by creating images with patches in different corners
# Patch types: white square, checkerboard, random noise
# Patch sizes: 3, 4, 5 pixels
# Positions: 1 pixel in from each corner (top-left, top-right, bottom-left, bottom-right)

def make_patch(patch_type, size):
    """Create a patch tensor of given type and size (C, H, W)"""
    if patch_type == 'white':
        return torch.ones(3, size, size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for c in range(3):
            for i in range(size):
                for j in range(size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
        return patch
    elif patch_type == 'random':
        return torch.randint(0, 2, (3, size, size)).float()
    return None

def apply_patch(images, patch, corner):
    """Apply patch to images at given corner (1 pixel in from edge)"""
    # images: (N, 3, 32, 32) uint8
    # patch: (3, size, size) float 0-1
    # corner: 'tl', 'tr', 'bl', 'br'
    result = images.clone().float() / 255.0
    _, _, h, w = patch.shape
    if corner == 'tl':
        result[:, :, 1:1+h, 1:1+w] = patch
    elif corner == 'tr':
        result[:, :, 1:1+h, 32-1-w:32-1] = patch
    elif corner == 'bl':
        result[:, :, 32-1-h:32-1, 1:1+w] = patch
    elif corner == 'br':
        result[:, :, 32-1-h:32-1, 32-1-w:32-1] = patch
    # Convert back to uint8
    result = (result * 255).clamp(0, 255).to(torch.uint8)
    return result

